    15→import { errors } from "../../strings/index.js";
    16→import { EXIT_CODES } from "../exit-codes.js";
    17→import { error, info, success, warn } from "../output.js";
    18→import { runSetupPipeline, type SetupPipelineResult } from "./setup.js";
    19→
    20→/**
    21→ * Default manifest template
    22→ */
    23→function generateManifest(projectName: string, singleFile: boolean): string {
    24→  const lines = [
    25→    `# ${projectName} - Kynetic Spec`,
    26→    `# Generated by kspec init`,
    27→    ``,
    28→    `kynetic: "1.0"`,
    29→    ``,
    30→    `project:`,
    31→    `  name: "${projectName}"`,
    32→    `  version: "0.1.0"`,
    33→    `  status: draft`,
    34→    `  description: |`,
    35→    `    Add your project description here.`,
    36→    ``,
    37→  ];
    38→
    39→  if (!singleFile) {
    40→    lines.push(
    41→      `# Module includes - add your spec modules here`,
    42→      `includes:`,
    43→      `  - modules/main.yaml`,
    44→      ``,
    45→    );
    46→  }
    47→
    48→  return lines.join("\n");
    49→}
    50→
    51→/**
    52→ * Default module template
    53→ */
    54→function generateMainModule(projectName: string): string {
    55→  return `# ${projectName} - Main Module
    56→# Add your spec items here
    57→
    58→items:
    59→  - _ulid: # Generate with: node -e "const {ulid} = require('ulid'); console.log(ulid())"
    60→    slugs: [example-feature]
    61→    type: feature
    62→    title: "Example Feature"
    63→    description: |
    64→      Describe your feature here.
    65→    status:
    66→      maturity: proposed
    67→      implementation: not_started
    68→`;
    69→}
    70→
    71→/**
    72→ * Default tasks file template
    73→ */
    74→function generateTasksFile(projectName: string): string {
    75→  return `# ${projectName} - Tasks
    76→# Track implementation work here
    77→
    78→tasks: []
    79→`;
    80→}
    81→
    82→/**
    83→ * Prompt user for input
    84→ */
    85→async function prompt(
    86→  question: string,
    87→  defaultValue?: string,
    88→): Promise<string> {
    89→  const rl = readline.createInterface({
    90→    input: process.stdin,
    91→    output: process.stdout,
    92→  });
    93→
    94→  try {
    95→    const suffix = defaultValue ? ` (${defaultValue})` : "";
    96→    const answer = await rl.question(`${question}${suffix}: `);
    97→    return answer.trim() || defaultValue || "";
    98→  } finally {
    99→    rl.close();
   100→  }
   101→}
   102→
   103→/**
   104→ * Derive project name from directory
   105→ */
   106→function deriveProjectName(targetDir: string): string {
   107→  const dirName = path.basename(path.resolve(targetDir));
   108→  // Convert kebab-case or snake_case to Title Case
   109→  return dirName.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
   110→}
   111→
   112→/**
   113→ * Convert project name to slug (kebab-case)
   114→ */
   115→function toSlug(projectName: string): string {
   116→  return projectName
   117→    .toLowerCase()
   118→    .replace(/[^a-z0-9]+/g, "-")
   119→    .replace(/^-|-$/g, "");
   120→}
   121→
   122→/**
   123→ * Register the 'init' command
   124→ * AC: @init-setup-integration ac-1 - shadow branch created and manifest exists
   125→ * AC: @init-setup-integration ac-2 - core skills installed in .kspec/skills/
   126→ * AC: @init-setup-integration ac-3 - rendered skill files, hooks, and kspec-agents.md present
   127→ * AC: @init-setup-integration ac-4 - without --setup, behavior unchanged
   128→ */
   129→export function registerInitCommand(program: Command): void {
   130→  program
   131→    .command("init [directory]")
   132→    .description("Initialize a new kspec project")
   133→    .option("-n, --name <name>", "Project name")
   134→    .option("--single-file", "Create manifest only (no modules directory)")
   135→    .option("--no-prompt", "Skip interactive prompts, use defaults")
   136→    .option("--force", "Overwrite existing files")
   137→    .option(
   138→      "--no-shadow",
   139→      "Skip shadow branch setup (create spec/ in main branch)",
   140→    )
   141→    .option(
   142→      "--setup",
   143→      "Run full setup after initialization (install core skills, hooks, render skills, generate agents.md)",
   144→    )
   145→    .action(async (directory, options) => {
   146→      try {
   147→        const targetDir = directory || process.cwd();
   148→        const useShadow = options.shadow !== false;
   149→
   150→        // Determine project name
   151→        let projectName = options.name;
   152→
   153→        if (!projectName && options.prompt !== false) {
   154→          const defaultName = deriveProjectName(targetDir);
   155→          projectName = await prompt("Project name", defaultName);
   156→        }
   157→
   158→        if (!projectName) {
   159→          projectName = deriveProjectName(targetDir);
   160→        }
   161→
   162→        // Shadow branch mode (default for git repos)
   163→        if (useShadow) {
   164→          const gitRoot = getGitRoot(targetDir);
   165→
   166→          if (!gitRoot) {
   167→            if (await isGitRepo(targetDir)) {
   168→              error(errors.git.couldNotDetermineRoot);
   169→              process.exit(EXIT_CODES.ERROR);
   170→            }
   171→            // Not a git repo - fall back to non-shadow mode with warning
   172→            warn(
   173→              "Not a git repository. Using non-shadow mode (spec/ in main branch).",
   174→            );
   175→            await initNonShadow(targetDir, projectName, options);
   176→            return;
   177→          }
   178→
   179→          // AC: @config-shadow — load project config for shadow settings
   180→          const configResult = await loadProjectConfig(gitRoot);
   181→          const config = configResult.config;
   182→
   183→          // Emit warning if config had issues
   184→          if (configResult.warning) {
   185→            warn(configResult.warning);
   186→          }
   187→
   188→          // Determine shadow options from config
   189→          const branchName = config.shadow.branch;
   190→          const directoryName = config.shadow.directory;
   191→          const shadowOptions = {
   192→            branchName,
   193→            directory: directoryName,
   194→            remote: config.shadow.remote?.value,
   195→            remoteType: config.shadow.remote?.type,
   196→          };
   197→
   198→          // AC: @config-shadow ac-9 — check for config mismatch
   199→          const mismatch = await checkConfigMismatch(
   200→            gitRoot,
   201→            branchName,
   202→            directoryName,
   203→          );
   204→          if (mismatch.hasMismatch && !options.force) {
   205→            warn("Shadow branch settings mismatch detected!");
   206→            console.log("");
   207→            console.log(mismatch.guidance);
   208→            console.log("");
   209→            console.log("Use --force to reinitialize with configured settings.");
   210→            process.exit(EXIT_CODES.ERROR);
   211→          }
   212→
   213→          info(`Initializing kspec project: ${projectName}`);
   214→          console.log(`  Mode: Shadow branch (${branchName} → ${directoryName}/)`);
   215→
   216→          const result = await initializeShadow(gitRoot, {
   217→            projectName,
   218→            force: options.force,
   219→            shadow: shadowOptions,
   220→          });
   221→
   222→          if (!result.success) {
   223→            error(
   224→              errors.project.shadowInitFailed(result.error || "Unknown error"),
   225→            );
   226→            process.exit(EXIT_CODES.ERROR);
   227→          }
   228→
   229→          if (result.alreadyExists) {
   230→            info("Shadow branch already initialized");
   231→          } else {
   232→            if (result.createdFromRemote) {
   233→              console.log(
   234→                `  Attached to existing remote branch: ${shadowOptions.remote || "origin"}/${branchName}`,
   235→              );
   236→              console.log("  Remote tracking configured");
   237→            } else if (result.branchCreated) {
   238→              console.log(`  Created orphan branch: ${branchName}`);
   239→              if (result.pushedToRemote) {
   240→                console.log(`  Pushed to remote: ${shadowOptions.remote || "origin"}/${branchName}`);
   241→              }
   242→            }
   243→            if (result.worktreeCreated) {
   244→              console.log(`  Created worktree: ${directoryName}/`);
   245→            }
   246→            if (result.gitignoreUpdated) {
   247→              console.log("  Updated .gitignore");
   248→            }
   249→            if (result.initialCommit) {
   250→              console.log("  Created initial spec files");
   251→            }
   252→          }
   253→
   254→          const slug = toSlug(projectName);
   255→
   256→          success(`Initialized kspec project in ${directoryName}/`, {
   257→            projectName,
   258→            mode: "shadow",
   259→            branch: branchName,
   260→          });
   261→
   262→          // AC: @init-setup-integration ac-2, ac-3 - Run full setup if --setup flag is passed
   263→          if (options.setup) {
   264→            console.log("\nRunning setup...\n");
   265→
   266→            const setupResult = await runSetupPipeline(gitRoot, {
   267→              dryRun: false,
   268→              skipSkills: false,
   269→              installHooks: true,
   270→            });
   271→
   272→            if (setupResult.success) {
   273→              console.log();
   274→              success("Setup complete. Your project is ready for use.");
   275→            } else {
   276→              warn(
   277→                "Setup encountered issues. Run 'kspec setup --status' for details.",
   278→              );
   279→            }
   280→          } else {
   281→            // AC: @init-setup-integration ac-4 - Without --setup, behavior unchanged
   282→            console.log("\nNext steps:");
   283→            console.log("  1. Run `kspec setup` for full agent integration");
   284→            console.log("  2. Run `kspec help` to explore available commands");
   285→            console.log(
   286→              `\nNote: Spec files live in ${directoryName}/ (gitignored) and commit to ${branchName} branch`,
   287→            );
   288→          }
   289→        } else {
   290→          // Non-shadow mode (legacy)
   291→          await initNonShadow(targetDir, projectName, options);
   292→        }
   293→      } catch (err) {
   294→        error(errors.failures.initProject, err);
   295→        process.exit(EXIT_CODES.ERROR);
   296→      }
   297→    });
   298→}
   299→
   300→/**
   301→ * Initialize in non-shadow mode (spec/ in main branch)
   302→ */
   303→async function initNonShadow(
   304→  targetDir: string,
   305→  projectName: string,
   306→  options: { force?: boolean; singleFile?: boolean },
   307→): Promise<void> {
   308→  const specDir = path.join(targetDir, "spec");
   309→
   310→  // Check if spec already exists
   311→  try {
   312→    await fs.access(specDir);
   313→    if (!options.force) {
   314→      error(errors.conflict.specDirExists(targetDir));
   315→      console.log("Use --force to overwrite existing files");
   316→      process.exit(EXIT_CODES.CONFLICT);
   317→    }
   318→    warn("Overwriting existing spec files");
   319→  } catch {
   320→    // Directory doesn't exist, good to proceed
   321→  }
   322→
   323→  const singleFile = options.singleFile || false;
   324→  const slug = toSlug(projectName);
   325→
   326→  info(`Initializing kspec project: ${projectName}`);
   327→  console.log("  Mode: Non-shadow (spec/ in main branch)");
   328→
   329→  // Create spec directory
   330→  await fs.mkdir(specDir, { recursive: true });
   331→
   332→  // Create manifest
   333→  const manifestPath = path.join(specDir, `${slug}.yaml`);
   334→  await fs.writeFile(
   335→    manifestPath,
   336→    generateManifest(projectName, singleFile),
   337→    "utf-8",
   338→  );
   339→  console.log(`  Created ${path.relative(targetDir, manifestPath)}`);
   340→
   341→  // Create tasks file
   342→  const tasksPath = path.join(specDir, `${slug}.tasks.yaml`);
   343→  await fs.writeFile(tasksPath, generateTasksFile(projectName), "utf-8");
   344→  console.log(`  Created ${path.relative(targetDir, tasksPath)}`);
   345→
   346→  if (!singleFile) {
   347→    // Create modules directory and main module
   348→    const modulesDir = path.join(specDir, "modules");
   349→    await fs.mkdir(modulesDir, { recursive: true });
   350→
   351→    const mainModulePath = path.join(modulesDir, "main.yaml");
   352→    await fs.writeFile(
   353→      mainModulePath,
   354→      generateMainModule(projectName),
   355→      "utf-8",
   356→    );
   357→    console.log(`  Created ${path.relative(targetDir, mainModulePath)}`);
   358→  }
   359→
   360→  success(
   361→    `Initialized kspec project in ${path.relative(process.cwd(), specDir) || "spec/"}`,
   362→    {
   363→      projectName,
   364→      specDir,
   365→      singleFile,
   366→      mode: "non-shadow",
   367→    },
   368→  );
   369→
   370→  console.log("\nNext steps:");
   371→  console.log(`  1. Edit spec/${slug}.yaml to customize your project`);
   372→  if (!singleFile) {
   373→    console.log("  2. Add spec items to spec/modules/main.yaml");
   374→  }
   375→  console.log(
   376→    `  ${singleFile ? "2" : "3"}. Run \`kspec tasks ready\` to see available tasks`,
   377→  );
   378→}
