   267→            execSync("git rebase --abort", {
   268→              cwd: worktreeDir,
   269→              stdio: "inherit",
   270→            });
   271→          }
   272→          // Force push to override remote
   273→          try {
   274→            execSync("git push --force-with-lease", {
   275→              cwd: worktreeDir,
   276→              stdio: "inherit",
   277→            });
   278→            success(shadowCommands.resolve.keptLocal);
