   291→          }
   292→
   293→          console.log(shadowCommands.resolve.interactive.options);
   294→          console.log();
   295→          console.log(shadowCommands.resolve.interactive.theirs.command);
   296→          console.log(shadowCommands.resolve.interactive.theirs.description);
   297→          console.log();
   298→          console.log(shadowCommands.resolve.interactive.ours.command);
   299→          console.log(shadowCommands.resolve.interactive.ours.description);
   300→          console.log();
   301→          console.log(shadowCommands.resolve.interactive.manual.header);
   302→          console.log(
   303→            shadowCommands.resolve.interactive.manual.cdCommand(
   304→              SHADOW_WORKTREE_DIR,
   305→            ),
   306→          );
   307→          if (inRebase) {
   308→            shadowCommands.resolve.interactive.manual.rebaseSteps.forEach(
   309→              (step) => console.log(step),
   310→            );
   311→          } else {
   312→            shadowCommands.resolve.interactive.manual.pullSteps.forEach(
   313→              (step) => console.log(step),
   314→            );
   315→          }
   316→        }
   317→      } catch (err) {
   318→        error(shadowCommands.resolve.failed, err);
   319→        process.exit(EXIT_CODES.ERROR);
   320→      }
   321→    });
   322→
   323→  // Explicit sync command
   324→  shadow
   325→    .command("sync")
   326→    .description("Manually sync shadow branch with remote (pull then push)")
   327→    .action(async () => {
   328→      try {
   329→        const gitRoot = getGitRoot(process.cwd());
   330→
   331→        if (!gitRoot) {
   332→          error(shadowCommands.notGitRepo);
